  `updated_at` timestamp NULL DEFAULT NULL,
  `roof_career` decimal(10,2) DEFAULT NULL,
  `new_vehicle` decimal(10,2) DEFAULT NULL,
  `security` decimal(10,2) DEFAULT NULL,
  `pet_friendly` decimal(10,2) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `categories_slug_unique` (`slug`)
