--
-- Table structure for table `orders`
--

DROP TABLE IF EXISTS `orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `orders` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) unsigned DEFAULT NULL,
  `driver_id` bigint(20) unsigned DEFAULT NULL,
  `transporter_id` bigint(20) unsigned DEFAULT NULL,
  `vehicle_id` bigint(20) unsigned DEFAULT NULL,
  `grand_total` decimal(10,2) DEFAULT NULL,
  `coupon_value` decimal(10,2) DEFAULT NULL,
  `coupon_name` varchar(255) DEFAULT NULL,
  `tax` decimal(10,2) DEFAULT NULL,
  `payment_method` varchar(255) DEFAULT NULL,
  `payment_status` varchar(255) DEFAULT NULL,
  `total_km` varchar(255) DEFAULT NULL,
  `date` date DEFAULT NULL,
  `dateTo` date DEFAULT NULL,
  `time` time DEFAULT NULL,
  `endTime` time DEFAULT NULL,
  `booking_from` varchar(255) DEFAULT NULL,
  `booking_to` varchar(255) DEFAULT NULL,
  `status` enum('new','start','modification','confirm','reconfirmation','cancelled','closed','refund') NOT NULL DEFAULT 'new',
  `plan` enum('none','4 Hour / 40 Km','8 Hour / 80 Km','12 Hour / 120 Km') NOT NULL DEFAULT 'none',
  `currency` varchar(255) DEFAULT NULL,
  `extraOptions` text DEFAULT NULL,
  `cityFrom` varchar(255) DEFAULT NULL,
  `cityTo` varchar(255) DEFAULT NULL,
  `productName` varchar(255) DEFAULT NULL,
  `image` varchar(255) DEFAULT NULL,
  `shipping_ammount` decimal(10,1) DEFAULT NULL,
  `taxi_type` varchar(255) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `ride_type` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `orders_user_id_foreign` (`user_id`),
  KEY `orders_driver_id_foreign` (`driver_id`),
  KEY `orders_transporter_id_foreign` (`transporter_id`),
  KEY `orders_vehicle_id_foreign` (`vehicle_id`),
  CONSTRAINT `orders_driver_id_foreign` FOREIGN KEY (`driver_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `orders_transporter_id_foreign` FOREIGN KEY (`transporter_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `orders_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `orders_vehicle_id_foreign` FOREIGN KEY (`vehicle_id`) REFERENCES `vehicles` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=217 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

