--
-- Table structure for table `products`
--

DROP TABLE IF EXISTS `products`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `products` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `category_id` bigint(20) unsigned DEFAULT NULL,
  `service_group` enum('with_driver','without_driver') NOT NULL DEFAULT 'with_driver',
  `vehicle_type` enum('car','bike','tempo') NOT NULL DEFAULT 'car',
  `brand_id` bigint(20) unsigned DEFAULT NULL,
  `booking_to` bigint(20) unsigned DEFAULT NULL,
  `name` varchar(255) DEFAULT NULL,
  `slug` varchar(255) DEFAULT NULL,
  `content_type` varchar(30) NOT NULL DEFAULT 'seo_page',
  `url_type` varchar(20) NOT NULL DEFAULT 'route',
  `ride_type` varchar(255) DEFAULT NULL,
  `price` decimal(10,2) DEFAULT NULL,
  `max_price` decimal(10,2) DEFAULT NULL,
  `km_limit` decimal(10,2) DEFAULT NULL,
  `hr_limit` decimal(10,2) DEFAULT NULL,
  `extra_km_charge` decimal(10,2) DEFAULT NULL,
  `extra_hr_charge` decimal(10,2) DEFAULT NULL,
  `toll_tax` decimal(10,2) DEFAULT NULL,
  `border_tax` decimal(10,2) DEFAULT NULL,
  `driver_allowances` decimal(10,2) DEFAULT NULL,
  `images` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `description` longtext DEFAULT NULL,
  `content_links` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`content_links`)),
  `fare_cards` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`fare_cards`)),
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `is_featured` tinyint(1) NOT NULL DEFAULT 0,
  `in_stock` tinyint(1) NOT NULL DEFAULT 1,
  `on_sale` tinyint(1) NOT NULL DEFAULT 0,
  `plan` enum('none','4 Hour / 40 Km','8 Hour / 80 Km','12 Hour / 120 Km') NOT NULL DEFAULT 'none',
  `meta_title` varchar(255) NOT NULL,
  `meta_description` varchar(255) NOT NULL,
  `focus_keyword` varchar(150) DEFAULT NULL,
  `canonical_url` varchar(500) DEFAULT NULL,
  `robots_index` tinyint(1) NOT NULL DEFAULT 1,
  `robots_follow` tinyint(1) NOT NULL DEFAULT 1,
  `seo_score` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `readability_score` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `seo_analysis` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`seo_analysis`)),
  `og_title` varchar(255) DEFAULT NULL,
  `og_description` text DEFAULT NULL,
  `og_image` varchar(500) DEFAULT NULL,
  `twitter_title` varchar(255) DEFAULT NULL,
  `twitter_description` text DEFAULT NULL,
  `twitter_image` varchar(500) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `products_slug_unique` (`slug`),
  KEY `products_category_id_foreign` (`category_id`),
  KEY `products_brand_id_foreign` (`brand_id`),
  KEY `products_booking_to_foreign` (`booking_to`),
  KEY `products_content_type_index` (`content_type`),
  KEY `products_url_type_index` (`url_type`),
  CONSTRAINT `products_booking_to_foreign` FOREIGN KEY (`booking_to`) REFERENCES `brands` (`id`) ON DELETE CASCADE,
  CONSTRAINT `products_brand_id_foreign` FOREIGN KEY (`brand_id`) REFERENCES `brands` (`id`) ON DELETE CASCADE,
  CONSTRAINT `products_category_id_foreign` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1979 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

